import logging
from taf.internal.managedobject import ManagedObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class K8sExecutor(ManagedObject):
    """
    Executor interface for K8s executor
    """

    def __init__(self, tool_executor, namespace, container, pod=None, **kwargs):
        """
        Create an K8s executor.

        :param tool_executor tool_executor: tool_executor to manage K8s executor.
        :param str namespace: Name space of the K8s
        :param str container: Name of the container in which instance to be executed
        :param str pod: Name of the pod in which instance to be executed
        """
        super(K8sExecutor, self).__init__(**kwargs)
        if pod is None:
            pod = ""
        self._pod = pod
        self._namespace = namespace
        self._container = container
        self._tool_executor = tool_executor
        self.add_prerequisite(tool_executor)

    def _setup(self):
        self._get_matching_pod_and_container_names()

    def raw_execute(self, command, use_tty=False, timeout=None):
        """
        Execute a command and wait until it finishes.

        :param bytes command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command
        :param float timeout: wait timeout seconds for the process to finish

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
        """
        command = self._prepare_command(command, use_tty)
        return self._tool_executor.raw_execute(command, use_tty=use_tty, timeout=timeout)

    def start(self, command, use_tty=False):
        """
        Start a command.

        Adds logging and optionally retry to start of command.

        :param bytes command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """
        k8s_command = self._prepare_command(command, use_tty)
        return self._tool_executor.start(k8s_command, use_tty=use_tty)

    def _prepare_command(self, command, use_tty):
        return ("kubectl exec -n {namespace} {pod} -c {container}{interactive} -- {command}".
                format(namespace=self._namespace,
                       pod=self._pod,
                       container=self._container,
                       interactive=" -it" if use_tty else ' -i',
                       command=command.decode()).encode())

    def execute(self, command, use_tty=False, timeout=None):
        """
        Execute a command.

        Adds logging and optionally retry to execute of command.

        :param bytes command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command
        :param float timeout: wait timeout seconds for the process to finish

        :return: bytes
        :rtype: bytes
        """
        k8s_command = self._prepare_command(command, use_tty)
        return self._tool_executor.execute(k8s_command, use_tty=use_tty, timeout=timeout)

    def __getattr__(self, name):
        return getattr(self._tool_executor, name)

    def _get_matching_pod_and_container_names(self):
        get_names_of_pod_and_container_for_pod_substring_and_container_substring = (
            """kubectl get pods -n {namespace} -o json | """
            """jq -r '.items[]|"\\(.metadata.name) \\(.spec.containers[]|.name)"' | """
            """grep '{pod}.* .*{container}'""".format(
                namespace=self._namespace,
                pod=self._pod,
                container=self._container)).encode()
        self._pod, self._container = self._tool_executor.execute(
            get_names_of_pod_and_container_for_pod_substring_and_container_substring).decode().split()
